            },
        ]
        self.check_request(
            {"command": "total", "lines": lines},
            {
                "release": "2.0",
                "credit_cents": 4500,
                "amount_due_cents": 35500,
            },
        )

    def test_release_2_assigns_cap_by_charge_then_line_id(self):
        lines = [
            {
                "line_id": "z-small",
                "account_id": "A",
                "subscription_id": "S",
                "service_on": "2026-01-01",
                "charge_cents": 10000,
            },
            {
                "line_id": "y-equal",
                "account_id": "A",
                "subscription_id": "S",
                "service_on": "2026-02-01",
                "charge_cents": 15000,
            },
            {
                "line_id": "x-equal",
                "account_id": "A",
                "subscription_id": "S",
                "service_on": "2026-03-01",
                "charge_cents": 15000,
