                "account_id": "A",
                "subscription_id": "S",
                "service_on": "2026-01-01",
                "charge_cents": 15000,
            },
        ]

        self.check_request(
            {"command": "statement", "release": "2.0", "lines": lines},
            {
                "release": "2.0",
                "lines": [
                    {
                        "line_id": "first-by-id",
                        "credit_cents": 2250,
                        "amount_due_cents": 12750,
                    },
                    {
                        "line_id": "second-by-id",
                        "credit_cents": 750,
                        "amount_due_cents": 14250,
                    },
                ],
                "credit_cents": 3000,
                "amount_due_cents": 27000,
            },
